from random import sample

def R():
	return map(int, input().split())

def ask(i):
	print('?', i, flush=True)
	(v, nxt) = R()
	if v < 0:
		exit()
	return (v, nxt)

def ans(v):
	print('!', v)
	exit()
(n, s, x) = R()
mv = -1
i = s
S = 800
q = range(1, n + 1)
if n > S:
	q = sample(q, S)
	if s not in q:
		q[0] = s
for i in q:
	(v, nxt) = ask(i)
	if v == x or (i == s and v > x):
		ans(v)
	if v < x:
		if nxt < 0:
			ans(-1)
		if v > mv:
			(mv, mnxt) = (v, nxt)
while mv < x and mnxt >= 1:
	(mv, mnxt) = ask(mnxt)
ans(mv if mv >= x else -1)
